/**
 * scripts/dm_features/dm-feature-registry.js
 *
 * Canonical DM-facing feature package declaration.
 * Registry mechanics and startup remain owned by the shared application runtime.
 */

import {
  FRAME_CONN_SITREP_FEATURES
} from "./sitreps/sitreps-feature-package.js";

export const FRAME_CONN_DM_FEATURES =
  Object.freeze([
    ...FRAME_CONN_SITREP_FEATURES
  ]);

/**
 * SITREP-specific spatial delegation boundary.
 * Owns no geometry, token-footprint math, Region implementation, or canvas lookup.
 */

const REQUIRED_SITREP_SPATIAL_OPERATIONS = Object.freeze([
  "resolveRegion",
  "tokenInsideRegion",
  "tokensAreAdjacent"
]);

export function assertSitrepSpatialOperations(operations) {
  if (!operations || typeof operations !== "object" || Array.isArray(operations)) {
    throw new TypeError("SITREP spatial operations must be supplied as an object.");
  }

  for (const operationName of REQUIRED_SITREP_SPATIAL_OPERATIONS) {
    if (typeof operations[operationName] !== "function") {
      throw new Error(`SITREP spatial operations require ${operationName}().`);
    }
  }

  return operations;
}

export function resolveConfiguredSitrepRegion(operations, combat, regionId) {
  assertSitrepSpatialOperations(operations);
  if (!regionId) return null;
  return operations.resolveRegion({ combat, regionId }) ?? null;
}

export function resolveConfiguredSitrepRegions(operations, combat, regionIds) {
  assertSitrepSpatialOperations(operations);
  const ids = Array.isArray(regionIds) ? regionIds : [];
  return ids
    .map(regionId => resolveConfiguredSitrepRegion(operations, combat, regionId))
    .filter(Boolean);
}

export function tokenInsideConfiguredSitrepRegion(operations, tokenDocument, region) {
  assertSitrepSpatialOperations(operations);
  if (!tokenDocument || !region) return false;
  return Boolean(operations.tokenInsideRegion(tokenDocument, region));
}

export async function sitrepTokensAreAdjacent(operations, firstToken, secondToken) {
  assertSitrepSpatialOperations(operations);
  if (!firstToken || !secondToken) return false;
  return Boolean(
    await operations.tokensAreAdjacent(firstToken, secondToken)
  );
}

/** Canonical Escort battlefield-state derivation. */

import {
  combatantById,
  combatantIsDefeated,
  collectStandingSitrepCombatants,
  SITREP_FACTIONS
} from "../shared/sitrep-combatant-primitives.js";
import {
  currentSitrepRound,
  sitrepRoundsRemaining
} from "../shared/sitrep-round-primitives.js";
import {
  resolveConfiguredSitrepRegion,
  sitrepTokensAreAdjacent,
  tokenInsideConfiguredSitrepRegion
} from "../shared/sitrep-spatial-delegation.js";

export async function calculateEscortState(
  combat,
  sitrep,
  spatialOperations
) {
  const state = {
    valid: false,
    currentRound: currentSitrepRound(combat, sitrep),
    roundsRemaining: sitrepRoundsRemaining(combat, sitrep),
    objectiveName: "Missing Objective",
    objectiveDestroyed: false,
    objectiveExtracted: sitrep?.escortStatus === "extracted",
    objectiveInExtraction: false,
    friendlyAdjacent: 0,
    hostileAdjacent: 0,
    canExtractObjective: false
  };

  if (!combat || !sitrep || sitrep.type !== "escort") return state;

  const extractionRegion =
    resolveConfiguredSitrepRegion(
      spatialOperations,
      combat,
      sitrep.escortExtractionRegionId
    );

  const objectiveCombatant =
    combatantById(
      combat,
      sitrep.escortObjectiveCombatantId
    );

  const objectiveToken =
    objectiveCombatant?.token ?? null;

  state.valid =
    Boolean(
      extractionRegion &&
      objectiveCombatant &&
      objectiveToken
    );

  if (!state.valid) return state;

  state.objectiveName =
    objectiveCombatant.name ||
    objectiveToken.name ||
    "Objective";

  state.objectiveDestroyed =
    sitrep.escortStatus === "destroyed" ||
    combatantIsDefeated(objectiveCombatant);

  state.objectiveExtracted =
    sitrep.escortStatus === "extracted";

  state.objectiveInExtraction =
    !state.objectiveDestroyed &&
    !state.objectiveExtracted &&
    tokenInsideConfiguredSitrepRegion(
      spatialOperations,
      objectiveToken,
      extractionRegion
    );

  for (const entry of collectStandingSitrepCombatants(combat)) {
    if (entry.token.id === objectiveToken.id) continue;

    if (
      !await sitrepTokensAreAdjacent(
        spatialOperations,
        entry.token,
        objectiveToken
      )
    ) {
      continue;
    }

    if (entry.faction === SITREP_FACTIONS.FRIENDLY) {
      state.friendlyAdjacent += 1;
    }

    if (entry.faction === SITREP_FACTIONS.HOSTILE) {
      state.hostileAdjacent += 1;
    }
  }

  state.canExtractObjective =
    state.objectiveInExtraction &&
    state.friendlyAdjacent > 0 &&
    state.hostileAdjacent === 0 &&
    !state.objectiveDestroyed &&
    !state.objectiveExtracted;

  return state;
}

/** Canonical Escort objective/result transitions. No chat, DOM, or hook ownership. */

import {
  readSitrepState,
  updateSitrepState
} from "../state/sitrep-state-service.js";
import {
  calculateEscortState
} from "./escort-state.js";

function outcomeIntent(status, reason, event) {
  return Object.freeze({
    kind: "sitrep-objective-result",
    sitrepType: "escort",
    event,
    status,
    reason
  });
}

export async function resolveEscortEncounterUpdate(
  combat,
  changes = {},
  spatialOperations
) {
  const sitrep = readSitrepState(combat);

  if (
    !combat ||
    !sitrep ||
    sitrep.type !== "escort" ||
    !sitrep.active ||
    sitrep.status !== "active"
  ) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  const state =
    await calculateEscortState(
      combat,
      sitrep,
      spatialOperations
    );

  if (!state.valid) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  let statePatch = null;
  let outputIntent = null;

  if (
    state.objectiveDestroyed &&
    sitrep.escortStatus !== "destroyed"
  ) {
    const reason =
      "The Objective was destroyed. Neither side achieved victory.";

    statePatch = {
      escortStatus: "destroyed",
      status: "draw",
      resultReason: reason
    };

    outputIntent =
      outcomeIntent(
        "draw",
        reason,
        "destroyed"
      );
  } else if (state.canExtractObjective) {
    const reason =
      "The Objective was safely extracted.";

    statePatch = {
      escortStatus: "extracted",
      status: "victory",
      resultReason: reason
    };

    outputIntent =
      outcomeIntent(
        "victory",
        reason,
        "extracted"
      );
  } else if (
    Object.prototype.hasOwnProperty.call(
      changes ?? {},
      "round"
    ) &&
    Number(changes.round) >
      Number(sitrep.finalRound)
  ) {
    const reason =
      `The Objective was not extracted by the end of round ${sitrep.finalRound}.`;

    statePatch = {
      status: "defeat",
      resultReason: reason
    };

    outputIntent =
      outcomeIntent(
        "defeat",
        reason,
        "round-limit"
      );
  }

  if (!statePatch) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      derivedState: state,
      outputIntent: null
    });
  }

  const nextState =
    await updateSitrepState(
      statePatch,
      combat
    );

  return Object.freeze({
    changed: true,
    state: nextState,
    derivedState: state,
    outputIntent
  });
}

/** Canonical Extraction battlefield-state derivation. */

import {
  combatantById,
  combatantIsDefeated,
  collectStandingSitrepCombatants,
  SITREP_FACTIONS
} from "../shared/sitrep-combatant-primitives.js";
import {
  currentSitrepRound,
  sitrepRoundsRemaining
} from "../shared/sitrep-round-primitives.js";
import {
  resolveConfiguredSitrepRegion,
  sitrepTokensAreAdjacent,
  tokenInsideConfiguredSitrepRegion
} from "../shared/sitrep-spatial-delegation.js";

export async function calculateExtractionState(
  combat,
  sitrep,
  spatialOperations
) {
  const state = {
    valid: false,
    currentRound: currentSitrepRound(combat, sitrep),
    roundsRemaining: sitrepRoundsRemaining(combat, sitrep),
    objectiveName: "Missing Objective",
    objectiveDestroyed: false,
    objectiveExtracted:
      sitrep?.extractionStatus === "extracted",
    objectiveInExtraction: false,
    friendlyAdjacent: 0,
    hostileAdjacent: 0,
    friendlyInExtractionZone: 0,
    canExtractObjective: false
  };

  if (
    !combat ||
    !sitrep ||
    sitrep.type !== "extraction"
  ) {
    return state;
  }

  const extractionRegion =
    resolveConfiguredSitrepRegion(
      spatialOperations,
      combat,
      sitrep.extractionZoneRegionId
    );

  const objectiveCombatant =
    combatantById(
      combat,
      sitrep.extractionObjectiveCombatantId
    );

  const objectiveToken =
    objectiveCombatant?.token ?? null;

  state.valid =
    Boolean(
      extractionRegion &&
      objectiveCombatant &&
      objectiveToken
    );

  if (!state.valid) return state;

  state.objectiveName =
    objectiveCombatant.name ||
    objectiveToken.name ||
    "Objective";

  state.objectiveDestroyed =
    sitrep.extractionStatus === "destroyed" ||
    combatantIsDefeated(objectiveCombatant);

  state.objectiveExtracted =
    sitrep.extractionStatus === "extracted";

  state.objectiveInExtraction =
    !state.objectiveDestroyed &&
    !state.objectiveExtracted &&
    tokenInsideConfiguredSitrepRegion(
      spatialOperations,
      objectiveToken,
      extractionRegion
    );

  for (const entry of collectStandingSitrepCombatants(combat)) {
    if (entry.token.id === objectiveToken.id) continue;

    if (
      entry.faction === SITREP_FACTIONS.FRIENDLY &&
      tokenInsideConfiguredSitrepRegion(
        spatialOperations,
        entry.token,
        extractionRegion
      )
    ) {
      state.friendlyInExtractionZone += 1;
    }

    if (
      !await sitrepTokensAreAdjacent(
        spatialOperations,
        entry.token,
        objectiveToken
      )
    ) {
      continue;
    }

    if (entry.faction === SITREP_FACTIONS.FRIENDLY) {
      state.friendlyAdjacent += 1;
    }

    if (entry.faction === SITREP_FACTIONS.HOSTILE) {
      state.hostileAdjacent += 1;
    }
  }

  state.canExtractObjective =
    state.objectiveInExtraction &&
    state.friendlyAdjacent > 0 &&
    state.hostileAdjacent === 0 &&
    !state.objectiveDestroyed &&
    !state.objectiveExtracted;

  return state;
}

/** Canonical Extraction objective/result transitions. No direct UI or chat ownership. */

import {
  readSitrepState,
  updateSitrepState
} from "../state/sitrep-state-service.js";
import {
  calculateExtractionState
} from "./extraction-state.js";

function objectiveIntent(event, status, reason) {
  return Object.freeze({
    kind: "sitrep-objective-result",
    sitrepType: "extraction",
    event,
    status,
    reason
  });
}

export async function resolveExtractionObjective(
  combat,
  outcome,
  spatialOperations
) {
  const sitrep = readSitrepState(combat);

  if (
    !combat ||
    !sitrep ||
    sitrep.type !== "extraction"
  ) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null,
      rejection: "not-extraction"
    });
  }

  const state =
    await calculateExtractionState(
      combat,
      sitrep,
      spatialOperations
    );

  if (!state.valid) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      derivedState: state,
      outputIntent: null,
      rejection: "invalid-objective-configuration"
    });
  }

  if (outcome === "extracted") {
    if (!state.canExtractObjective) {
      return Object.freeze({
        changed: false,
        state: sitrep,
        derivedState: state,
        outputIntent: null,
        rejection: "objective-not-extractable"
      });
    }

    const reason =
      "The Objective was safely recovered and extracted.";

    const nextState =
      await updateSitrepState(
        {
          extractionStatus: "extracted",
          status: "victory",
          resultReason: reason
        },
        combat
      );

    return Object.freeze({
      changed: true,
      state: nextState,
      derivedState: state,
      outputIntent:
        objectiveIntent(
          "extracted",
          "victory",
          reason
        ),
      rejection: null
    });
  }

  if (outcome === "destroyed") {
    const reason =
      "The Objective was destroyed. Neither side achieved victory.";

    const nextState =
      await updateSitrepState(
        {
          extractionStatus: "destroyed",
          status: "draw",
          resultReason: reason
        },
        combat
      );

    return Object.freeze({
      changed: true,
      state: nextState,
      derivedState: state,
      outputIntent:
        objectiveIntent(
          "destroyed",
          "draw",
          reason
        ),
      rejection: null
    });
  }

  return Object.freeze({
    changed: false,
    state: sitrep,
    derivedState: state,
    outputIntent: null,
    rejection: "unknown-outcome"
  });
}

export async function resolveExtractionEncounterUpdate(
  combat,
  changes = {},
  spatialOperations
) {
  const sitrep = readSitrepState(combat);

  if (
    !combat ||
    !sitrep ||
    sitrep.type !== "extraction" ||
    !sitrep.active ||
    sitrep.status !== "active"
  ) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  const state =
    await calculateExtractionState(
      combat,
      sitrep,
      spatialOperations
    );

  if (!state.valid) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  if (
    state.objectiveDestroyed &&
    sitrep.extractionStatus !== "destroyed"
  ) {
    return resolveExtractionObjective(
      combat,
      "destroyed",
      spatialOperations
    );
  }

  if (
    Object.prototype.hasOwnProperty.call(
      changes ?? {},
      "round"
    ) &&
    Number(changes.round) >
      Number(sitrep.finalRound)
  ) {
    const reason =
      `The Objective was not extracted by the end of round ${sitrep.finalRound}. Any allied units remaining on the battlefield are captured or overrun.`;

    const nextState =
      await updateSitrepState(
        {
          status: "defeat",
          resultReason: reason
        },
        combat
      );

    return Object.freeze({
      changed: true,
      state: nextState,
      derivedState: state,
      outputIntent:
        objectiveIntent(
          "round-limit",
          "defeat",
          reason
        )
    });
  }

  return Object.freeze({
    changed: false,
    state: sitrep,
    derivedState: state,
    outputIntent: null
  });
}

/** Canonical SITREP application orchestration. Runtime composition is supplied by the authoritative Frame Conn orchestrator. */

import {
  clearSitrepState,
  readSitrepState,
  readSitrepStateRecord,
  updateSitrepState,
  writeSitrepState
} from "../state/sitrep-state-service.js";
import {
  resolveGauntletEncounterUpdate
} from "../gauntlet/gauntlet-resolution.js";
import {
  resolveControlEncounterUpdate
} from "../control/control-resolution.js";
import {
  resolveHoldoutEncounterUpdate
} from "../holdout/holdout-resolution.js";
import {
  resolveEscortEncounterUpdate
} from "../escort/escort-resolution.js";
import {
  resolveExtractionEncounterUpdate,
  resolveExtractionObjective
} from "../extraction/extraction-resolution.js";
import {
  recordReconScan,
  resolveReconEncounterUpdate
} from "../recon/recon-resolution.js";
import {
  buildConfiguredSitrepState,
  validateSitrepSetup
} from "./sitrep-setup.js";

const runtime = {
  spatialOperations: null,
  publishOutputIntent: null,
  canManageSitreps:
    () =>
      Boolean(
        globalThis.game?.user?.isGM
      )
};

export function configureSitrepOrchestrationRuntime({
  spatialOperations,
  publishOutputIntent,
  canManageSitreps
} = {}) {
  if (spatialOperations !== undefined) {
    runtime.spatialOperations =
      spatialOperations;
  }

  if (publishOutputIntent !== undefined) {
    if (
      publishOutputIntent !== null &&
      typeof publishOutputIntent !== "function"
    ) {
      throw new TypeError(
        "SITREP output publisher must be a function or null."
      );
    }

    runtime.publishOutputIntent =
      publishOutputIntent;
  }

  if (canManageSitreps !== undefined) {
    if (typeof canManageSitreps !== "function") {
      throw new TypeError(
        "SITREP authorization binding must be a function."
      );
    }

    runtime.canManageSitreps =
      canManageSitreps;
  }

  return getSitrepOrchestrationDiagnostics();
}

function assertManagePermission() {
  if (!runtime.canManageSitreps()) {
    throw new Error(
      "Only the authoritative GM may manage SITREPs."
    );
  }
}

function requireSpatialOperations() {
  if (!runtime.spatialOperations) {
    throw new Error(
      "SITREP spatial operations have not been configured."
    );
  }

  return runtime.spatialOperations;
}

function requireOutputPublisher() {
  if (typeof runtime.publishOutputIntent !== "function") {
    throw new Error(
      "SITREP semantic output publishing has not been configured."
    );
  }

  return runtime.publishOutputIntent;
}

async function publishIntent(intent) {
  if (!intent) return null;

  return requireOutputPublisher()(
    intent
  );
}

async function publishResultIntents(result) {
  if (!result) return result;

  const intents =
    Array.isArray(result.outputIntents)
      ? result.outputIntents
      : result.outputIntent
        ? [result.outputIntent]
        : [];

  for (const intent of intents) {
    await publishIntent(intent);
  }

  return result;
}

export function getSitrepOperationalState(
  combat = null
) {
  return readSitrepStateRecord(combat);
}

export function getSitrepOrchestrationDiagnostics() {
  return Object.freeze({
    spatialConfigured:
      Boolean(runtime.spatialOperations),

    outputPublisherConfigured:
      typeof runtime.publishOutputIntent ===
        "function",

    authorizationConfigured:
      typeof runtime.canManageSitreps ===
        "function"
  });
}

export async function configureSitrep(
  request,
  combat = null
) {
  assertManagePermission();

  const existing =
    readSitrepState(combat);

  return writeSitrepState(
    buildConfiguredSitrepState(
      request,
      combat,
      existing,
      {
        resetProgress: false
      }
    ),
    combat
  );
}

export async function startSitrep(
  request,
  combat = null
) {
  assertManagePermission();

  const existing =
    readSitrepState(combat);

  const state =
    await writeSitrepState(
      buildConfiguredSitrepState(
        request,
        combat,
        existing,
        {
          resetProgress: true
        }
      ),
      combat
    );

  await publishIntent(
    Object.freeze({
      kind: "sitrep-started",
      sitrepType: state.type,
      title: state.title,
      finalRound: state.finalRound
    })
  );

  return state;
}

export async function toggleSitrepPause(
  combat = null
) {
  assertManagePermission();

  const sitrep =
    readSitrepState(combat);

  if (!sitrep) {
    throw new Error(
      "Cannot pause or resume because no SITREP is configured."
    );
  }

  return updateSitrepState(
    {
      status:
        sitrep.status === "paused"
          ? "active"
          : "paused"
    },
    combat
  );
}

export async function endSitrep(
  combat = null
) {
  assertManagePermission();

  await clearSitrepState(combat);

  await publishIntent(
    Object.freeze({
      kind: "sitrep-ended"
    })
  );

  return null;
}

export async function setSitrepResult(
  status,
  reason,
  combat = null
) {
  assertManagePermission();

  const normalizedStatus =
    String(status ?? "")
      .trim()
      .toLowerCase();

  if (
    ![
      "victory",
      "defeat",
      "draw"
    ].includes(normalizedStatus)
  ) {
    throw new Error(
      `Unsupported SITREP result status: ${normalizedStatus}.`
    );
  }

  const resultReason =
    String(reason ?? "").trim();

  const state =
    await updateSitrepState(
      {
        status: normalizedStatus,
        resultReason
      },
      combat
    );

  const outputIntent =
    Object.freeze({
      kind: "sitrep-result",
      sitrepType: state.type,
      status: normalizedStatus,
      reason: resultReason
    });

  await publishIntent(outputIntent);

  return Object.freeze({
    changed: true,
    state,
    outputIntent
  });
}

const encounterResolvers =
  Object.freeze({
    gauntlet:
      resolveGauntletEncounterUpdate,

    control:
      resolveControlEncounterUpdate,

    holdout:
      resolveHoldoutEncounterUpdate,

    escort:
      resolveEscortEncounterUpdate,

    extraction:
      resolveExtractionEncounterUpdate,

    recon:
      resolveReconEncounterUpdate
  });

export async function evaluateSitrepCombatChange(
  combat,
  changes = {}
) {
  if (!runtime.canManageSitreps()) {
    return Object.freeze({
      changed: false,
      state: readSitrepState(combat),
      outputIntent: null
    });
  }

  const sitrep =
    readSitrepState(combat);

  if (
    !sitrep?.active ||
    sitrep.status !== "active"
  ) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  const resolver =
    encounterResolvers[
      sitrep.type
    ];

  if (!resolver) {
    return Object.freeze({
      changed: false,
      state: sitrep,
      outputIntent: null
    });
  }

  return publishResultIntents(
    await resolver(
      combat,
      changes,
      requireSpatialOperations()
    )
  );
}

export async function handleSitrepCombatUpdate(
  combat,
  changes = {}
) {
  try {
    return await evaluateSitrepCombatChange(
      combat,
      changes
    );
  } catch (error) {
    console.error(
      "Frame Conn | SITREP combat evaluation failed.",
      error
    );

    return Object.freeze({
      changed: false,
      state:
        readSitrepState(combat),
      outputIntent: null,
      error
    });
  }
}

export async function scanReconRegion(
  combat,
  regionId
) {
  assertManagePermission();

  return publishResultIntents(
    await recordReconScan(
      combat,
      regionId,
      requireSpatialOperations()
    )
  );
}

export async function resolveExtractionOutcome(
  combat,
  outcome
) {
  assertManagePermission();

  return publishResultIntents(
    await resolveExtractionObjective(
      combat,
      outcome,
      requireSpatialOperations()
    )
  );
}

export {
  validateSitrepSetup
};

